# Single source for requirements (spec chapter 5) and validation test cases (VTS).
# Requirement: Id, Dom, Text, Pri, Ver (T/D/I/A), Acc, Closes
$Domains = [ordered]@{
  'SW'  = '5.1 Software and instrumentation requirements'
  'TST' = '5.2 Qualification layer requirements'
  'INF' = '5.3 Infrastructure requirements'
  'SEC' = '5.4 Security and privacy requirements'
  'DQ'  = '5.5 Telemetry data-quality requirements'
  'OPS' = '5.6 Operations and governance requirements'
}
$Reqs = @(
 @{Id='SW-01';Text='All Java services run the OpenTelemetry Java agent injected by the OTel Operator, one pinned version per platform release, with database semantic-convention opt-in, propagators tracecontext and baggage, OTLP logs and trace-based exemplars.';Pri='M';Ver='T,I';Acc='Every component in the inventory emits spans, metrics and logs with service.name equal to its deployment name; agent version recorded in the evidence manifest.';Closes='VER-02'}
 @{Id='SW-02';Text='A MOSIP agent extension sets business keys on spans and in the logging MDC: mosip.rid, mosip.uin_hash, mosip.vid_hash, mosip.request_id, mosip.partner_id, mosip.reg_type, mosip.stage. Never the NIN, VID or other personal data in clear.';Pri='M';Ver='T';Acc='Every regproc, ID repository, IDA, resident and credential span of a test journey carries the expected keys; PII scan finds no clear identifier.';Closes='INST-01, INST-04'}
 @{Id='SW-03';Text='Context propagation through the registration processor event bus (Vert.x / Kafka) and JMS (ABIS) is verified; where the agent does not propagate, the extension injects and extracts traceparent and baggage in message headers.';Pri='M';Ver='T';Acc='For NIN-001 every stage consumer span descends from the packet-receiver span in the same trace.';Closes='INST-02'}
 @{Id='SW-04';Text='Span links for asynchronous breaks: the credential request stores the originating traceparent and the batch job links to it; WebSub callbacks carry the publisher context and IDA links to it.';Pri='S';Ver='T';Acc='Traces T2 and T3 of NIN-001 each hold a span link resolvable to trace T1.';Closes='INST-02'}
 @{Id='SW-05';Text='Audit to trace correlation: the audit client adds trace_id and span_id to each audit event, stored with the event, and each audit event is also emitted as an OTLP log to the audit tenant.';Pri='M';Ver='T';Acc='Every audit row of a test journey is matched to its producing span by id; audit counts in database and audit tenant are equal.';Closes='INST-03'}
 @{Id='SW-06';Text='Structured JSON logs on all services: UTC timestamp, level, logger, message key, trace_id, span_id and MDC business keys; stable message keys for oracle matching.';Pri='M';Ver='T';Acc='100 % of log records emitted inside a span carry trace_id and span_id.';Closes='INST-01'}
 @{Id='SW-07';Text='Business metrics with OpenTelemetry naming and units: stage processed / failed / reprocessed, UIN and VID pool levels, ABIS round-trip time, credential issuance time, notifications sent and failed, packets queued at stations.';Pri='S';Ver='T,I';Acc='Metrics exist with agreed names and labels; dashboards and alert rules use them.';Closes='-'}
 @{Id='SW-08';Text='Registration client instrumented with the OTel Java SDK; the enrolment traceparent is stored with the encrypted packet and restored by the packet receiver; local telemetry buffer bounded and flushed on reconnect; station clock synchronised.';Pri='M';Ver='T';Acc='Offline variant of NIN-001: station and central spans share one trace id after the agreed offline window.';Closes='INST-05'}
 @{Id='SW-09';Text='Web and mobile front ends instrumented with OTel browser / mobile SDKs; traceparent on every API call (CORS allows traceparent, tracestate, baggage); consent-aware; no personal data in attributes.';Pri='S';Ver='T';Acc='A resident-portal update journey shows the browser span as root of the backend trace.';Closes='INST-06'}
 @{Id='SW-10';Text='The ingress / API gateway creates a server span for every partner call, records mosip.partner_id and accepts inbound traceparent only from authorised partners; partner simulators are instrumented.';Pri='S';Ver='T';Acc='Bank-authentication scenario shows partner id and remote parent on the first IDA span.';Closes='INST-07'}
 @{Id='SW-11';Text='Each service exposes build information (version, commit, image digest) via actuator and resource attributes service.version and vcs.ref.head.revision.';Pri='M';Ver='I';Acc='The evidence manifest lists version and digest of every component for each run.';Closes='VER-01'}
 @{Id='TST-01';Text='Jarvis opens one ROOT span per scenario with baggage cicd.pipeline.run.id, test.suite.name, test.case.name; step spans as children; results on the ROOT span (test.case.result.status, acme.test.verdict).';Pri='M';Ver='T';Acc='Every scenario run has exactly one ROOT span with these attributes.';Closes='-'}
 @{Id='TST-02';Text='Evidence collector: settle window, queries to traces, logs (app and audit tenants), metrics, read-only databases, business APIs and Kubernetes; manifest with exact queries; SHA-256 per file; signature; upload to the evidence bucket.';Pri='M';Ver='T';Acc='A verdict can be recomputed from the bundle alone (replay).';Closes='-'}
 @{Id='TST-03';Text='Oracle engine with matcher language, JSON Schemas for oracle, persona and prerequisite files validated in CI, golden-run record-review-freeze workflow, and classification into seven verdict classes.';Pri='M';Ver='T';Acc='CI rejects an invalid oracle; a golden run needs an approving review; injected faults produce the expected verdict class.';Closes='-'}
 @{Id='TST-04';Text='Oracles declare the MOSIP release and agent version they apply to; a platform upgrade triggers re-recording of golden runs and a reviewed diff.';Pri='M';Ver='T';Acc='Running an oracle against a non-matching release stops with ENV_NOT_READY.';Closes='VER-01'}
 @{Id='TST-05';Text='Synthetic data generator compliant with the live ID schema and persona contracts (demographics, documents, ISO 19794 biometrics via mock MDS), deterministic by seed, unique against the gallery.';Pri='M';Ver='T';Acc='1 000 generated residents validate against the ID schema; no ABIS hit unless requested.';Closes='-'}
 @{Id='TST-06';Text='Instrumented mocks and simulators: ABIS (NO_HIT, HIT, TIMEOUT, FAILURE), SMTP / SMS with read API, relying-party simulator, WebSub subscriber; mode selectable per scenario.';Pri='M';Ver='T';Acc='Each mode is selectable through an API and visible in traces.';Closes='-'}
 @{Id='TST-07';Text='Reports with per-clause expected / actual / evidence file, probable first source and Grafana deep link; results exported to the test-management tool by scenario tag.';Pri='S';Ver='D';Acc='Every failed check links to an evidence file and a Grafana URL.';Closes='-'}
 @{Id='INF-01';Text='Observability stack per site: OTel Operator, collector agent (DaemonSet) and gateway (at least 2 replicas, load balancing by trace id), Tempo, Loki with platform and audit tenants, Mimir, Grafana, Alertmanager.';Pri='M';Ver='T';Acc='Canary signal from every node retrievable in less than [60 s] on each site.';Closes='-'}
 @{Id='INF-02';Text='Object storage with object lock (WORM) for audit-tenant data and the evidence bucket, replicated from DC1 to DC2.';Pri='M';Ver='T';Acc='Delete or overwrite on locked objects fails; replica present on DC2.';Closes='-'}
 @{Id='INF-03';Text='Tenants per platform class (dev, test, int, perf) plus audit; every signal carries deployment.environment.name, k8s.cluster.name and acme.site.name stamped by the cluster collector.';Pri='M';Ver='T';Acc='Environment and site checks ENV-02 and ENV-03 pass on every platform.';Closes='-'}
 @{Id='INF-04';Text='Capacity sized for [X] spans/s, [Y] log lines/s and [Z] active series per platform; load-tested before the first campaign.';Pri='M';Ver='T,A';Acc='Collector refused and failed counters stay at 0 at [1.5x] nominal load.';Closes='-'}
 @{Id='INF-05';Text='NTP / chrony on all nodes, stations and simulators with offset at most [50 ms].';Pri='M';Ver='T,I';Acc='Offset alert below threshold; oracle clock-skew tolerance never exceeded.';Closes='-'}
 @{Id='INF-06';Text='OTLP endpoints internal only, network policies, monitored DC1 to DC2 links, synthetic probes.';Pri='M';Ver='T';Acc='Network policies tested; site-to-site probe metrics available.';Closes='-'}
 @{Id='INF-07';Text='Sync job from the environment configuration manager to GitOps (namespace annotations, Instrumentation resource, collector stamp, Jarvis prerequisites) with drift detection.';Pri='M';Ver='T';Acc='Drift check runs before every campaign and on every change, and detects an injected mismatch.';Closes='-'}
 @{Id='INF-08';Text='Everything as code (GitOps): collector configuration, dashboards, alert rules, retention, tenants, oracles; changes only by reviewed pull request.';Pri='M';Ver='T,I';Acc='A manual change in the cluster is reverted by the next sync.';Closes='-'}
 @{Id='INF-09';Text='Ephemeral test namespaces on demand with pre-seeded masterdata, SoftHSM keys and partners, isolated from shared traffic.';Pri='S';Ver='T';Acc='NIN-001 in an ephemeral namespace passes with exact metric assertions.';Closes='ENV-01'}
 @{Id='INF-10';Text='CI runners for Jarvis on each platform with access restricted to MOSIP endpoints, observability APIs and the evidence bucket.';Pri='M';Ver='T';Acc='Runner network policy allows only these destinations.';Closes='-'}
 @{Id='INF-11';Text='Backup and disaster recovery of observability stores and evidence.';Pri='S';Ver='T';Acc='Restore test documented; evidence readable from DC2 after loss of DC1.';Closes='-'}
 @{Id='SEC-01';Text='No personal data in telemetry: deny-list (NIN, VID, names, phone, email, address, biometrics, document numbers) enforced at source and at the gateway; continuous automated PII scan.';Pri='M';Ver='T';Acc='PII scan returns 0 on every run; a seeded PII value is caught (negative test).';Closes='-'}
 @{Id='SEC-02';Text='mosip.uin_hash uses the MOSIP salted hash; the investigator lookup helper runs as a restricted service and every lookup is audited.';Pri='M';Ver='D,I';Acc='Lookup audit records exist for each search; the salt is never exposed to browsers or test code.';Closes='INST-04'}
 @{Id='SEC-03';Text='SSO (OIDC) and RBAC per platform and tenant; audit tenant readable by auditors only; read-only service accounts for Jarvis and evidence collector; databases through read-only replicas and roles.';Pri='M';Ver='T';Acc='Access matrix tested; denied queries logged.';Closes='-'}
 @{Id='SEC-04';Text='TLS (mTLS in the mesh) for OTLP and backend APIs; credentials in a vault; nothing secret in repositories.';Pri='M';Ver='T';Acc='Plain-text connections refused; repository secret scan clean.';Closes='-'}
 @{Id='SEC-05';Text='Baggage stripped on egress to third parties; inbound traceparent accepted only from authorised partners; baggage size capped at [8 KB]; no personal data or secrets in baggage.';Pri='M';Ver='T';Acc='Egress capture shows no baggage header to partner simulators.';Closes='INST-07'}
 @{Id='SEC-06';Text='Evidence integrity: SHA-256 per file, bundle signature, optional RFC 3161 timestamp, object lock for the retention period.';Pri='M';Ver='T';Acc='Altering one file makes bundle verification fail.';Closes='-'}
 @{Id='SEC-07';Text='Synthetic data only on non-production platforms; DPIA of the observability platform; retention limits enforced (NDPA 2023 [A]).';Pri='M';Ver='I';Acc='DPIA approved; retention policies visible in configuration.';Closes='-'}
 @{Id='SEC-08';Text='Pinned and signed images for agent, collector and backends; SBOM per release; vulnerability scanning in CI.';Pri='S';Ver='T';Acc='An unsigned image is rejected by the admission policy.';Closes='-'}
 @{Id='SEC-09';Text='Artefacts carry their classification; public repositories contain no environment URLs, hostnames, keys or real identifiers.';Pri='M';Ver='I';Acc='Pre-publication scan and manual review recorded for public repositories.';Closes='-'}
 @{Id='DQ-01';Text='Pinned semantic-convention version and a published attribute registry, including the organisation namespace.';Pri='M';Ver='T,I';Acc='Registry versioned; CI lint rejects unknown custom attributes.';Closes='VER-02'}
 @{Id='DQ-02';Text='Signal contract per component checked in CI and on each platform; part of every work package Definition of Done.';Pri='M';Ver='D';Acc='Contract job present in each work package pipeline and blocking.';Closes='-'}
 @{Id='DQ-03';Text='Cardinality budget: metric label whitelist (environment, site, cluster, service, route, status); no identifiers as metric labels.';Pri='M';Ver='A,T';Acc='Active series per service under the agreed budget.';Closes='-'}
 @{Id='DQ-04';Text='Sampling policy per platform with test-tagged traffic always kept.';Pri='M';Ver='T';Acc='No test-tagged trace missing in the trace store.';Closes='-'}
 @{Id='OPS-01';Text='Pipeline health objectives (receive / export failures, ingestion lag, canary freshness); a run during a breach is automatically INCONCLUSIVE.';Pri='M';Ver='T';Acc='Injected pipeline failure yields INCONCLUSIVE.';Closes='-'}
 @{Id='OPS-02';Text='Provisioned dashboards and alerts: platform health, journey per run, stage RED metrics, audit completeness, PII scan, DR.';Pri='S';Ver='I';Acc='Dashboards and alerts loaded from Git and routed.';Closes='-'}
 @{Id='OPS-03';Text='Governance: owners for attribute registry, oracles, golden-run approval and platform; change advisory for agent and convention upgrades.';Pri='M';Ver='I';Acc='Roles and responsibilities published; upgrade checklist used.';Closes='-'}
 @{Id='OPS-04';Text='Runbooks and platform support during qualification campaigns, including triage of INCONCLUSIVE and INFRA verdicts.';Pri='S';Ver='I';Acc='Runbooks in Git; support rota during campaigns.';Closes='-'}
 @{Id='OPS-05';Text='Onboarding guide and training for work-package teams.';Pri='S';Ver='D';Acc='Each team has executed one scenario end to end.';Closes='-'}
)
$Gaps = @(
 @('INST-01','RID not on spans and logs','SW-02, SW-06'),
 @('INST-02','Credential batch and WebSub start new traces','SW-03, SW-04'),
 @('INST-03','Audit table has no trace id','SW-05'),
 @('INST-04','No privacy-safe NIN key on IDA, resident and ID repository spans','SW-02, SEC-02'),
 @('INST-05','Offline station breaks the trace at sync','SW-08'),
 @('INST-06','Web and mobile front ends do not start or propagate traces','SW-09'),
 @('INST-07','Third-party partner calls are opaque','SW-10, SEC-05'),
 @('VER-01','DB columns, stage codes, API paths vary between MOSIP patches','SW-11, TST-04'),
 @('VER-02','Span names and attributes vary with agent and convention versions','SW-01, DQ-01'),
 @('ENV-01','Shared traffic makes metric deltas inexact','INF-09')
)

# Validation test cases. Mode: S simulation, F full (NIN-001 on MOSIP), I inspection, D demonstration.
$TCs = @(
 @{Id='VT-INF-01';Title='Canary signal end to end on every site and platform';Mode='S';Reqs='INF-01, OPS-01';Pre='Stack deployed on DC1 and DC2; canary job configured.';Steps=@('Emit one canary span, log and metric per node with telemetrygen (resource attributes of the node).','Query Tempo, Loki and Mimir for the canary ids.','Measure the delay between emission and availability.');Exp='All canary signals retrievable on each site within [60 s]; site and environment attributes present.';Ev='Canary ids, query results, timings.'}
 @{Id='VT-INF-02';Title='Object lock on audit and evidence buckets';Mode='S';Reqs='INF-02, SEC-06';Pre='Buckets created by Terraform with object lock.';Steps=@('Upload a test object to the evidence bucket with retention.','Attempt delete and overwrite with an administrator role.','Check the replica on DC2.');Exp='Delete and overwrite refused; replica present on DC2.';Ev='API responses, bucket policy export.'}
 @{Id='VT-INF-03';Title='Environment and site stamping overrides application values';Mode='S';Reqs='INF-03, INF-07';Pre='Collector agent with site stamp from the environment manager.';Steps=@('Send spans with telemetrygen declaring a wrong deployment.environment.name and acme.site.name.','Query the stored spans.');Exp='Stored resource attributes equal the environment-manager values, not the sent ones.';Ev='Sent payload, stored span.'}
 @{Id='VT-INF-04';Title='Ingest capacity at 1.5x nominal load';Mode='S';Reqs='INF-04, DQ-04';Pre='Agreed nominal rates [X], [Y], [Z].';Steps=@('Generate traces, logs and metrics with telemetrygen at 1.5x nominal for [30 min].','Watch collector refused / failed counters and ingestion lag.');Exp='Refused and failed counters stay at 0; lag within objective; test-tagged traces all kept.';Ev='Collector self-metrics, load profile.'}
 @{Id='VT-INF-05';Title='Clock synchronisation';Mode='I';Reqs='INF-05';Pre='NTP / chrony configured.';Steps=@('Read the clock offset metric of every node, station and simulator.');Exp='Offset at most [50 ms] everywhere.';Ev='Offset metrics export.'}
 @{Id='VT-INF-06';Title='Network exposure of OTLP and runner egress';Mode='S';Reqs='INF-06, INF-10';Pre='Network policies applied.';Steps=@('Attempt OTLP connection from outside the cluster.','From a CI runner, attempt a connection to a non-allowed destination.');Exp='Both connections refused; allowed destinations reachable.';Ev='Connection logs.'}
 @{Id='VT-INF-07';Title='Environment manager drift detection';Mode='S';Reqs='INF-07';Pre='Sync job and drift check deployed.';Steps=@('Change the site value of one collector manually.','Run the drift check.');Exp='Drift reported with the exact attribute and cluster; campaign blocked (ENV_NOT_READY).';Ev='Drift report.'}
 @{Id='VT-INF-08';Title='GitOps reconciliation';Mode='S';Reqs='INF-08';Pre='Argo CD managing the observability namespace.';Steps=@('Edit a collector config map directly in the cluster.','Wait for the next sync.');Exp='Manual change reverted; drift alarm raised.';Ev='Sync history.'}
 @{Id='VT-INF-09';Title='Ephemeral namespace with exact metric deltas';Mode='F';Reqs='INF-09';Pre='Ephemeral namespace template available.';Steps=@('Create an ephemeral MOSIP slice.','Run NIN-001 with metric assertions set to exact equality.');Exp='NIN-001 PASS with exact deltas.';Ev='Evidence bundle.'}
 @{Id='VT-INF-10';Title='Backup, restore and DC2 evidence availability';Mode='S';Reqs='INF-11';Pre='Backup jobs configured.';Steps=@('Restore observability stores from backup on a test cluster.','Read an evidence bundle from DC2 with DC1 endpoints disabled.');Exp='Restore succeeds; bundle verifies from DC2.';Ev='Restore log, verification output.'}
 @{Id='VT-PIPE-01';Title='OTLP replay of the NIN-001 example through the full pipeline';Mode='S';Reqs='TST-02, DQ-04, SW-11';Pre='Example file oracles/examples/NIN-001.otlp-example.json; timestamps shifted to now.';Steps=@('POST the traces, logs and metrics blocks to the agent OTLP/HTTP endpoints /v1/traces, /v1/logs, /v1/metrics.','Retrieve the trace by id from Tempo, the log record from Loki and the metric and exemplar from Mimir.','Normalise Tempo ids from base64 to hex and compare with the sent payload.');Exp='All 7 spans, the log record and the histogram data point retrieved; parent links intact; exemplar points to span 53995c3f42cd8ad8.';Ev='Replay payload, query results, comparison report.'}
 @{Id='VT-PIPE-02';Title='Tail sampling keeps test and error traces';Mode='S';Reqs='DQ-04';Pre='PERF sampling policy active.';Steps=@('Send 1 000 untagged traces, 100 traces with test.case.name, 50 traces with ERROR status.','Count stored traces per category.');Exp='All test-tagged and error traces stored; untagged traces sampled at about [10 %].';Ev='Counts per category.'}
 @{Id='VT-PIPE-03';Title='PII redaction at the gateway';Mode='S';Reqs='SEC-01';Pre='Redaction processor configured.';Steps=@('Send a span and a log record containing a fake 11-digit NIN, an email and a phone number in attributes and body.','Query the stored records.');Exp='Values masked or removed in storage; redaction counter incremented.';Ev='Sent and stored records.'}
 @{Id='VT-PIPE-04';Title='Audit routing and multiset equality';Mode='S';Reqs='SW-05, SEC-03';Pre='Routing to the audit tenant configured.';Steps=@('Send 20 audit log records (stream mosip-audit) and 20 application records.','Query both tenants with and without the auditor role.');Exp='Audit records only in the audit tenant; readable by auditors only; counts equal to sent.';Ev='Query results per role.'}
 @{Id='VT-PIPE-05';Title='Span metrics and exemplars';Mode='S';Reqs='SW-07, DQ-03';Pre='Spanmetrics connector and exemplars enabled.';Steps=@('Replay NIN-001 spans.','Query traces_span_metrics_calls_total and query_exemplars for the packet-receiver route.');Exp='Counter incremented with environment and site labels; exemplar carries the replayed trace id; no identifier used as a label.';Ev='PromQL results.'}
 @{Id='VT-PIPE-06';Title='Pipeline failure leads to INCONCLUSIVE';Mode='S';Reqs='OPS-01, TST-03';Pre='Pipeline health objectives configured.';Steps=@('Scale the gateway to 0 replicas.','Run a simulated scenario and the evidence collector.','Restore the gateway.');Exp='Verdict INCONCLUSIVE with pipeline-health reason; never PASS.';Ev='verdict.json, health metrics.'}
 @{Id='VT-SW-01';Title='Agent present and pinned on every component';Mode='F';Reqs='SW-01, SW-11';Pre='Platform deployed.';Steps=@('List pods with injected agent and versions.','Read the evidence manifest of a NIN-001 run.');Exp='Every inventory component instrumented with the pinned version; manifest lists versions and digests.';Ev='Inventory export, manifest.'}
 @{Id='VT-SW-02';Title='Business keys on spans and logs, no clear identifiers';Mode='F';Reqs='SW-02, SW-06';Pre='Extension deployed.';Steps=@('Run NIN-001.','Check mosip.rid and mosip.uin_hash on all expected spans and trace_id / span_id on log records.','Run the PII scan.');Exp='Keys present on 100 % of expected spans; logs correlated; PII scan 0.';Ev='Oracle check results.'}
 @{Id='VT-SW-03';Title='Propagation across Kafka and JMS stages';Mode='F';Reqs='SW-03';Pre='NIN-001 executable.';Steps=@('Run NIN-001.','Check that every stage consumer span descends from the packet-receiver span.');Exp='Single trace T1 across all stages, ABIS included or linked.';Ev='Trace export.'}
 @{Id='VT-SW-04';Title='Span links for credential batch and WebSub';Mode='F';Reqs='SW-04';Pre='Extension and patch deployed.';Steps=@('Run NIN-001.','Resolve links of T2 and T3.');Exp='Both links resolve to spans of T1.';Ev='Trace exports.'}
 @{Id='VT-SW-05';Title='Audit trace correlation';Mode='F';Reqs='SW-05';Pre='Audit patch deployed.';Steps=@('Run NIN-001.','Join audit rows to spans by trace_id and span_id.');Exp='Every audit row joined; database and audit-tenant counts equal.';Ev='Join report.'}
 @{Id='VT-SW-06';Title='Business metrics present';Mode='F';Reqs='SW-07';Pre='Metrics implemented.';Steps=@('Run NIN-001.','Query each agreed business metric.');Exp='All metrics exist with agreed names, units and labels and move as expected.';Ev='PromQL results.'}
 @{Id='VT-SW-07';Title='Offline station trace continuity';Mode='F';Reqs='SW-08, INF-05';Pre='Instrumented registration client.';Steps=@('Enrol a resident with the station offline for the agreed window.','Reconnect and let it sync.');Exp='Station spans and central spans share one trace id; no packet or telemetry lost.';Ev='Trace export, station buffer log.'}
 @{Id='VT-SW-08';Title='Front-end root span';Mode='F';Reqs='SW-09';Pre='Instrumented resident portal.';Steps=@('Run the resident update journey from a browser.');Exp='Browser span is root of the backend trace; no personal data in browser attributes.';Ev='Trace export.'}
 @{Id='VT-SW-09';Title='Partner edge: remote parent and partner id';Mode='S';Reqs='SW-10, SEC-05';Pre='Relying-party simulator.';Steps=@('Call the authentication API from an authorised simulator with a traceparent, then from an unauthorised one.','Capture egress towards the simulator.');Exp='Authorised call: remote parent kept and mosip.partner_id set; unauthorised: new trace; no baggage on egress.';Ev='Traces, egress capture.'}
 @{Id='VT-SEC-01';Title='PII scan negative test';Mode='S';Reqs='SEC-01';Pre='PII scan job.';Steps=@('Bypass the redaction on a test pipeline and send a seeded fake NIN.','Run the PII scan.');Exp='Seeded value detected and reported.';Ev='Scan report.'}
 @{Id='VT-SEC-02';Title='NIN lookup helper restricted and audited';Mode='D';Reqs='SEC-02';Pre='Lookup helper deployed.';Steps=@('Search one NIN as an investigator.','Attempt the same as a user without the role.','Inspect the lookup audit.');Exp='Authorised search returns journeys; unauthorised refused; both attempts audited; salt not exposed.';Ev='Audit records, screenshots.'}
 @{Id='VT-SEC-03';Title='Access control matrix';Mode='S';Reqs='SEC-03';Pre='SSO and roles configured.';Steps=@('For each role, query each tenant and the evidence bucket.');Exp='Results match the access matrix; denials logged.';Ev='Matrix results.'}
 @{Id='VT-SEC-04';Title='Transport security and secrets';Mode='S';Reqs='SEC-04';Pre='TLS enabled.';Steps=@('Attempt a plain-text OTLP and API connection.','Run a secret scan on all repositories.');Exp='Plain text refused; no secret found.';Ev='Connection log, scan report.'}
 @{Id='VT-SEC-05';Title='Baggage hygiene';Mode='S';Reqs='SEC-05';Pre='Egress gateway rule.';Steps=@('Send a request with baggage that triggers a call to a partner simulator.','Send an oversized baggage header.');Exp='No baggage on egress; oversized baggage rejected or truncated.';Ev='Egress capture.'}
 @{Id='VT-SEC-06';Title='Evidence tamper detection';Mode='S';Reqs='SEC-06, TST-02';Pre='Sealed bundle from a simulated run.';Steps=@('Modify one byte of logs.ndjson in a copy of the bundle.','Run bundle verification.');Exp='Verification fails naming the altered file.';Ev='Verification output.'}
 @{Id='VT-SEC-07';Title='Data protection inspection';Mode='I';Reqs='SEC-07';Pre='DPIA and retention configuration.';Steps=@('Inspect the DPIA, data sources and retention settings.');Exp='Synthetic data only; DPIA approved; retention configured as agreed.';Ev='Inspection record.'}
 @{Id='VT-SEC-08';Title='Supply-chain admission';Mode='S';Reqs='SEC-08';Pre='Admission policy enabled.';Steps=@('Deploy an unsigned collector image.');Exp='Deployment rejected.';Ev='Admission log.'}
 @{Id='VT-SEC-09';Title='Public repository review';Mode='I';Reqs='SEC-09';Pre='Repository public.';Steps=@('Run a scan for URLs, hostnames, keys and identifiers; manual review.');Exp='No sensitive content; review recorded.';Ev='Scan and review record.'}
 @{Id='VT-DQ-01';Title='Attribute registry lint';Mode='S';Reqs='DQ-01';Pre='Lint job in CI.';Steps=@('Submit a change emitting an unknown custom attribute.');Exp='CI fails naming the attribute.';Ev='CI log.'}
 @{Id='VT-DQ-02';Title='Signal contract in Definition of Done';Mode='D';Reqs='DQ-02';Pre='Work-package pipelines.';Steps=@('Show the contract job in each pipeline; break a contract on purpose.');Exp='Pipeline blocked.';Ev='Pipeline runs.'}
 @{Id='VT-DQ-03';Title='Cardinality budget';Mode='S';Reqs='DQ-03';Pre='Budget agreed.';Steps=@('Count active series per service after a NIN-001 run and a load test.');Exp='Under budget; no identifier label.';Ev='Series counts.'}
 @{Id='VT-QUAL-01';Title='ROOT span and baggage';Mode='S';Reqs='TST-01';Pre='Jarvis configured.';Steps=@('Run a simulated scenario.','Inspect ROOT span and child spans.');Exp='One ROOT span with required attributes; baggage values on all child spans.';Ev='Trace export.'}
